cat > public/app.js <<'EOF'
// Load the user's projects and render them. The projects API is cursor-paginated:
// each response is an envelope { page, page_size, total, next, results: [...] },
// where `next` is the URL of the following page (null on the last page).

const API_URL = "./data/items.json";

function render(items) {
  const list = document.getElementById("items");
  const empty = document.getElementById("empty");
  if (!items || items.length === 0) {
    empty.style.display = "block";
    list.innerHTML = "";
    return;
  }
  empty.style.display = "none";
  list.innerHTML = items.map((p) => `<li>${p.name}</li>`).join("");
}

async function load() {
  const spinner = document.getElementById("spinner");
  try {
    const all = [];
    let url = API_URL;
    while (url) {
      const res = await fetch(url);
      const data = await res.json();
      all.push(...(data.results || []));
      url = data.next;
    }
    spinner.style.display = "none";
    render(all);
  } catch (err) {
    console.error("failed to load projects", err);
  }
}

load();
EOF
